title: Support cluster failover for stateful workloads
authors:
  - "@XiShanYongYe-Chang"
reviewers:
  - "@mszacillo"
  - "@Dyex719"
  - "@RainbowMango"
approvers:
  - "@kevin-wangzefeng"
